    inline constexpr FMissionStageDefinition Mission12Stages[] = {
        { TEXT("date_the_print"), TEXT("Show Nika Vidmar the torn photograph from the cashbox."), TEXT("nika_vidmar"), TEXT("Show Nika the torn photograph"), EObjectiveType::Interaction, nullptr, 0, 1, false, Mission12Stage0Required, UE_ARRAY_COUNT(Mission12Stage0Required), nullptr, 0, nullptr, 0, nullptr, 0, false, TEXT("Nika turns it over before she looks at the picture. 'Our stamp, the 1989 one. Fotokemika paper, the batch with the cream base. February 1990, give or take a week.' She cannot find the negative: 'Strips go back to the customer in the envelope. My father kept the books, not the film.'") },
        { TEXT("read_order_book"), TEXT("Look up February 1990 in the Foto Vidmar order book on the counter beside Nika."), TEXT("foto_vidmar_order_book"), TEXT("Read the order book"), EObjectiveType::Interaction, nullptr, 0, 1, false, nullptr, 0, nullptr, 0, nullptr, 0, nullptr, 0, false, TEXT("Order 0217, in her father's square hand: 'Vogrin I., 36 posn., 20.2.1990', collected on the 23rd. One roll of thirty-six, developed and contact-printed. The name is a fact on a page; why that roll was taken is not.") },
        { TEXT("copy_order_book"), TEXT("The book stays in the lab. Photograph the open page so you carry a copy: stand at the counter, frame the book and press [P]."), TEXT("foto_vidmar_order_book_page"), TEXT("Photograph the page"), EObjectiveType::Photograph, nullptr, 0, 1, false, nullptr, 0, nullptr, 0, nullptr, 0, nullptr, 0, false, TEXT("A copy of the entry, sharp enough to read. Nika pencils her initials and today's date in the margin of the book: whoever reads it next will know someone looked.") },
        { TEXT("ask_drago"), TEXT("Drago Poto\u010Dnik drove for Raeda in 1990. Ask him whether anyone else kept prints from that February."), TEXT("drago_potocnik"), TEXT("Ask about the prints"), EObjectiveType::Interaction, nullptr, 0, 1, false, nullptr, 0, Mission12Stage3Grants, UE_ARRAY_COUNT(Mission12Stage3Grants), nullptr, 0, nullptr, 0, false, TEXT("Drago takes a small print from his wallet: himself at twenty-five beside a new cab-over truck, the Foto Vidmar stamp and '36' on the back. 'Stefan from correspondence took it. Irena brought her camera that day and he ran about with it. Stefan kept everything. Ask his widow, in Block 13.'") },
        { TEXT("ask_ivana"), TEXT("Find Ivana Zupan at Block 13 in Tabor and ask about her late husband's photographs."), TEXT("ivana_zupan"), TEXT("Ask about Stefan's photographs"), EObjectiveType::Interaction, nullptr, 0, 1, false, nullptr, 0, nullptr, 0, nullptr, 0, nullptr, 0, false, TEXT("'He photographed the office the way other men photograph their children.' She gives you the key to the storage cage, and a condition: 'Bring back what you borrow. I would like a receipt.'") },
        { TEXT("open_cage"), TEXT("Open the Zupan storage cage and go through Stefan's office boxes."), TEXT("block_13_storage_cage"), TEXT("Search Stefan's boxes"), EObjectiveType::Interaction, nullptr, 0, 1, false, nullptr, 0, Mission12Stage5Grants, UE_ARRAY_COUNT(Mission12Stage5Grants), nullptr, 0, nullptr, 0, false, TEXT("Between carbon copies and a returned registered letter you leave sealed, a Foto Vidmar envelope, order 0217, holds one contact sheet. No negatives. Frames 34 and 35 are the gate photograph, 36 is Drago and the truck, and after 36 there is a 37th: fogged, almost nothing.") },
        { TEXT("copy_contact_sheet"), TEXT("Lay the contact sheet on Nika's light table and photograph it under even light, so the original can go back into safe keeping."), TEXT("zupan_contact_sheet_copy"), TEXT("Photograph the contact sheet"), EObjectiveType::Photograph, nullptr, 0, 1, false, Mission12Stage6Required, UE_ARRAY_COUNT(Mission12Stage6Required), nullptr, 0, nullptr, 0, nullptr, 0, false, TEXT("Under the opal glass the fog on frame 37 has a shape in it: the corner of something tall, and a board. Your photograph is a copy; the sheet is the original, and from now on you will have to say which is which.") },
        { TEXT("frame_37_print"), TEXT("Frame 37 is a thumbnail on the sheet. Ask Nika how to get a print you can actually read."), TEXT("nika_vidmar"), TEXT("Compare Frame 37 with Nika's print"), EObjectiveType::InventoryAny, Mission12Stage7Items, UE_ARRAY_COUNT(Mission12Stage7Items), 1, false, nullptr, 0, nullptr, 0, nullptr, 0, nullptr, 0, false, TEXT("Nika lays the enlargement over the sheet. Same fog, same scratch across the corner: frame 37 of order 0217. 'Now the scrap has a roll, a customer and a date. Before, it was a nice mystery. Now it is evidence.'") },
        { TEXT("chronology"), TEXT("Take the Frame 37 print, your photograph of the Melje yard's date board and the Kainach serial photographs to Vera Horvat."), TEXT("vera_horvat"), TEXT("Lay out the chronology"), EObjectiveType::Interaction, nullptr, 0, 1, false, Mission12Stage8Required, UE_ARRAY_COUNT(Mission12Stage8Required), Mission12Stage8Grants, UE_ARRAY_COUNT(Mission12Stage8Grants), Mission12Stage8Flags, UE_ARRAY_COUNT(Mission12Stage8Flags), nullptr, 0, false, TEXT("Vera reads the settlement's summary aloud: 'Kainach arrangement closed without obligation, December 1989.' Then she finds K 07 on your serial photograph, on the print, and the board above it. 'Sixteenth of February. Two months after it closed, it was still delivering trucks.' She will not say who lied: 'That is an inference. Write it down as one.'") },
        { TEXT("glas_full_frame"), TEXT("The Glas ran one frame from this roll beside Prehod-Kainach's notice in April 1990. Ask at the Mariborski Glas archive desk for the photo desk's print."), TEXT("mariborski_glas_archive"), TEXT("Ask for the photo desk's print"), EObjectiveType::Interaction, nullptr, 0, 1, false, Mission12Stage9Required, UE_ARRAY_COUNT(Mission12Stage9Required), Mission12Stage9Grants, UE_ARRAY_COUNT(Mission12Stage9Grants), nullptr, 0, nullptr, 0, false, TEXT("The photo desk's bromide is uncropped, with grease-pencil marks where the paper trimmed it. The archivist makes you a copy of the strip your print is missing. Seven people, not six: a man in a foreign overcoat with a clipboard and, sharp at the edge, a face you know from Kiosk 67. Albin Rojko.") },
        { TEXT("albin_willing"), TEXT("Albin Rojko, the Kiosk 67 customer, is working mornings with Matej now. Show him the strip."), TEXT("kiosk_67_customer"), TEXT("Show Albin the strip"), EObjectiveType::Interaction, nullptr, 0, 1, false, Mission12Stage10Required, UE_ARRAY_COUNT(Mission12Stage10Required), Mission12Stage10Grants, UE_ARRAY_COUNT(Mission12Stage10Grants), nullptr, 0, nullptr, 0, false, TEXT("Albin wipes his hands on a rag from Hall Three before he takes the copy. 'You found me work when I was hiding. I will not hide from this.' Ten o'clock, 16 February: the trucks driven in, the man from Kainach ticking them off, Lorber's car at the gate. 'Nobody asked for the council's stamp. It was in my pocket. I said nothing.'"), Mission12Stage10When, UE_ARRAY_COUNT(Mission12Stage10When) },
        { TEXT("albin_hesitates"), TEXT("Albin Rojko, the Kiosk 67 customer, is back at his old routine. Show him the strip."), TEXT("kiosk_67_customer"), TEXT("Show Albin the strip"), EObjectiveType::Interaction, nullptr, 0, 1, false, Mission12Stage11Required, UE_ARRAY_COUNT(Mission12Stage11Required), nullptr, 0, nullptr, 0, nullptr, 0, false, TEXT("He looks at his own face for a long time. 'The tab is settled and I am grateful. This is a different debt.' He hands the copy back. 'Ask Petra what I was like in 1990. Then ask me again.'"), Mission12Stage11When, UE_ARRAY_COUNT(Mission12Stage11When) },
        { TEXT("petra_word"), TEXT("Ask Petra Kralj what Albin was like in 1990."), TEXT("petra_kralj"), TEXT("Ask about Albin"), EObjectiveType::Interaction, nullptr, 0, 1, false, nullptr, 0, nullptr, 0, nullptr, 0, nullptr, 0, false, TEXT("'He bought the Delo and the Glas, both, so he could complain about both. That spring he bought neither for a month.' Petra folds a paper for him without being asked. 'Take him this. Tell him I said to stop being proud.'"), Mission12Stage12When, UE_ARRAY_COUNT(Mission12Stage12When) },
        { TEXT("albin_second_talk"), TEXT("Go back to Albin with Petra's message."), TEXT("kiosk_67_customer"), TEXT("Ask Albin again"), EObjectiveType::Interaction, nullptr, 0, 1, false, Mission12Stage13Required, UE_ARRAY_COUNT(Mission12Stage13Required), Mission12Stage13Grants, UE_ARRAY_COUNT(Mission12Stage13Grants), nullptr, 0, nullptr, 0, false, TEXT("He laughs once at Petra's message, then tells it plainly. Ten o'clock, 16 February: the trucks driven in, the man from Kainach ticking them off, Lorber's car at the gate. 'Nobody asked for the council's stamp. It was in my pocket. I said nothing. Petra is right: I have been proud about the wrong thing.'"), Mission12Stage13When, UE_ARRAY_COUNT(Mission12Stage13When) },
        { TEXT("albin_stamp"), TEXT("Show Albin Rojko, the Kiosk 67 customer, the strip."), TEXT("kiosk_67_customer"), TEXT("Show Albin the strip"), EObjectiveType::Interaction, nullptr, 0, 1, false, Mission12Stage14Required, UE_ARRAY_COUNT(Mission12Stage14Required), nullptr, 0, nullptr, 0, nullptr, 0, false, TEXT("'The thing you helped me sell,' he says. 'It was the council stamp from the machine hall. I carried it to the gate that day and never took it out of my pocket.' He will not say more without it in his hand. 'Ernest Pavli\u010D has it. He buys anything with a factory's name on it.'"), Mission12Stage14When, UE_ARRAY_COUNT(Mission12Stage14When) },
        { TEXT("buy_back_stamp"), TEXT("Get the machine-hall council stamp back from Ernest Pavli\u010D, the collector near the Glas archive."), TEXT("stamp_collector"), TEXT("Ask about the stamp"), EObjectiveType::Choice, nullptr, 0, 1, false, nullptr, 0, nullptr, 0, nullptr, 0, Mission12Stage15Choices, UE_ARRAY_COUNT(Mission12Stage15Choices), false, TEXT(""), Mission12Stage15When, UE_ARRAY_COUNT(Mission12Stage15When) },
        { TEXT("albin_with_stamp"), TEXT("Bring Albin his council stamp."), TEXT("kiosk_67_customer"), TEXT("Give Albin the stamp"), EObjectiveType::InventoryAny, Mission12Stage16Items, UE_ARRAY_COUNT(Mission12Stage16Items), 1, true, Mission12Stage16Required, UE_ARRAY_COUNT(Mission12Stage16Required), Mission12Stage16Grants, UE_ARRAY_COUNT(Mission12Stage16Grants), nullptr, 0, nullptr, 0, false, TEXT("He holds the stamp the way you would hold a tool you have not used in years. Ten o'clock, 16 February: the trucks driven in, the man from Kainach ticking them off, Lorber's car at the gate. 'This should have been on the transfer. Nobody asked for it, and I did not offer.'"), Mission12Stage16When, UE_ARRAY_COUNT(Mission12Stage16When) },
        { TEXT("albin_refuses"), TEXT("Show Albin Rojko, the Kiosk 67 customer, the strip."), TEXT("kiosk_67_customer"), TEXT("Show Albin the strip"), EObjectiveType::Interaction, nullptr, 0, 1, false, Mission12Stage17Required, UE_ARRAY_COUNT(Mission12Stage17Required), nullptr, 0, nullptr, 0, nullptr, 0, false, TEXT("He does not take the copy. 'You came looking for me once and then you left me be. Leave me be now.' He turns back to the street. Petra once said he complains about football; somebody he watches it with may know how to reach him."), Mission12Stage17When, UE_ARRAY_COUNT(Mission12Stage17When) },
        { TEXT("match_day_circle"), TEXT("Find the terrace regulars Albin watches the match with, by the Kiosk 67 caf\u00E9, and ask one of them to vouch for you."), TEXT("viole_terrace_regular"), TEXT("Ask about Albin"), EObjectiveType::Interaction, nullptr, 0, 1, false, nullptr, 0, Mission12Stage18Grants, UE_ARRAY_COUNT(Mission12Stage18Grants), nullptr, 0, nullptr, 0, false, TEXT("Boris hears you out without looking away from the radio. 'Albin sits with us on Saturdays because nobody asks him anything there.' He ties a faded purple scarf round your wrist. 'Show him that. It means we said you were all right.'"), Mission12Stage18When, UE_ARRAY_COUNT(Mission12Stage18When) },
        { TEXT("albin_match_day"), TEXT("Go back to Albin with the circle's scarf."), TEXT("kiosk_67_customer"), TEXT("Show Albin the scarf"), EObjectiveType::Interaction, nullptr, 0, 1, false, Mission12Stage19Required, UE_ARRAY_COUNT(Mission12Stage19Required), Mission12Stage19Grants, UE_ARRAY_COUNT(Mission12Stage19Grants), nullptr, 0, nullptr, 0, false, TEXT("He looks at the scarf, then at you. 'Boris does not vouch for anybody.' Ten o'clock, 16 February: the trucks driven in, the man from Kainach ticking them off, Lorber's car at the gate. 'Nobody asked for the council's stamp. I said nothing. Write that I said nothing; it is the truest part.'"), Mission12Stage19When, UE_ARRAY_COUNT(Mission12Stage19When) },
        { TEXT("the_ticket"), TEXT("Bring Nika the bus ticket from the cashbox, Albin's account and the original contact sheet."), TEXT("nika_vidmar"), TEXT("Lay it all out for Nika"), EObjectiveType::InventoryAny, Mission12Stage20Items, UE_ARRAY_COUNT(Mission12Stage20Items), 1, true, Mission12Stage20Required, UE_ARRAY_COUNT(Mission12Stage20Required), Mission12Stage20Grants, UE_ARRAY_COUNT(Mission12Stage20Grants), Mission12Stage20Flags, UE_ARRAY_COUNT(Mission12Stage20Flags), nullptr, 0, true, TEXT("Nika reads the punch on the ticket: Melje line, 16 February 1990, the morning of frame 35. 'The order book names the camera's owner, and the ticket puts her at the gate.' She locks the contact sheet in the lab safe in Ivana's name and writes you a receipt. 'Now you know who stood behind the camera's owner. That is not the same as knowing why.'") },
    };

